const S="hide";
// ---- BODY: crouched, hexagonal section, scaled hide ----
const body=[];
body.push(box({at:[-2,0,-7],size:[4,3,16],colour:"belly"}));
body.push(box({at:[-4,3,-8],size:[8,9,18],colour:S,texture:"masonry"}));
range(-8,10,2).forEach(z=>{
  body.push(place({part:"3660b",at:[-4,3,z],colour:S,turn:90}));
  body.push(place({part:"3660b",at:[2,3,z],colour:S,turn:270}));
  body.push(place({part:"3039",at:[-4,12,z],colour:S,turn:90}));
  body.push(place({part:"3039",at:[2,12,z],colour:S,turn:270}));
});
body.push(box({at:[-2,12,-8],size:[4,3,18],colour:S}));
range(-8,10).forEach(z=>{
  body.push(place({part:"3040b",at:[-2,15,z],colour:S,turn:90}));
  body.push(place({part:"3040b",at:[0,15,z],colour:S,turn:270}));
});
range(-7,9,3).forEach(z=>body.push(place({part:"15070",at:[-1,18,z],colour:"spine"})));
section("Body",body);
// ---- NECK: rearing S-curve ----
const neck=[];
range(6).forEach(k=>{
  const y=6+4*k, z=-10-2*k;
  neck.push(box({at:[-2,y,z],size:[4,8,4],colour:S,texture:"masonry"}));
  if(k<5){ const top=y+8, ez=z+2;
    neck.push(place({part:"3040b",at:[-2,top,ez],colour:S,turn:180}));
    neck.push(place({part:"3040b",at:[0,top,ez],colour:S,turn:180}));
    neck.push(place({part:"3040b",at:[1,top,ez],colour:S,turn:180}));
    neck.push(place({part:"15070",at:[-1,top,ez],colour:"spine"}));
  }
  neck.push(place({part:"3660b",at:[-2,y-3,z],colour:S,turn:0}));
  neck.push(place({part:"3660b",at:[0,y-3,z],colour:S,turn:0}));
});
section("Neck",neck);
// ---- HEAD ----
const head=[];
head.push(box({at:[-3,32,-24],size:[6,7,8],colour:S}));
head.push(box({at:[-2,33,-30],size:[4,3,6],colour:S}));
head.push(place({part:"3298",at:[-2,36,-29],colour:S}));
head.push(place({part:"3298",at:[0,36,-29],colour:S}));
head.push(place({part:"6141",at:[-2,36,-26],colour:"trans yellow"}));
head.push(place({part:"6141",at:[1,36,-26],colour:"trans yellow"}));
head.push(place({part:"54200",at:[-2,36,-25],colour:"spine"}));
head.push(place({part:"54200",at:[1,36,-25],colour:"spine"}));
head.push(place({part:"3069b",at:[-1,36,-26],colour:S}));
head.push(place({part:"3069b",at:[-1,36,-25],colour:S}));
head.push(place({part:"6141",at:[-2,36,-30],colour:"spine"}));
head.push(place({part:"6141",at:[1,36,-30],colour:"spine"}));
head.push(place({part:"3069b",at:[-1,36,-30],colour:S}));
// upper teeth hang from the snout
[[-2,-30],[1,-30],[-2,-28],[1,-28]].forEach(([x,z])=>head.push(place({part:"3024",at:[x,32,z],colour:"white"})));
// lower jaw, open
head.push(box({at:[-2,24,-28],size:[4,3,10],colour:S}));
[[-2,-28],[1,-28],[-2,-26],[1,-26]].forEach(([x,z])=>head.push(place({part:"54200",at:[x,27,z],colour:"white"})));
head.push(place({part:"3040b",at:[-1,27,-28],colour:S}));
head.push(place({part:"3040b",at:[0,27,-28],colour:S}));
head.push(place({part:"3660b",at:[-2,21,-28],colour:S}));
head.push(place({part:"3660b",at:[0,21,-28],colour:S}));
// fire in the mouth
head.push(place({part:"3062b",at:[-1,30,-30],colour:"trans orange"}));
head.push(place({part:"3062b",at:[0,30,-30],colour:"trans orange"}));
head.push(place({part:"4589",at:[-1,27,-30],colour:"trans yellow"}));
head.push(place({part:"4589",at:[0,27,-30],colour:"trans yellow"}));
// crest: horns, side frills, spines
head.push(place({part:"2142",at:[-3,39,-19],colour:"spine"}));
head.push(place({part:"2142",at:[1,39,-19],colour:"spine"}));
range(-24,-19).forEach(z=>{head.push(place({part:"3040b",at:[-3,39,z],colour:S,turn:90}));head.push(place({part:"3040b",at:[1,39,z],colour:S,turn:270}));});
[-24,-22,-20].forEach(z=>head.push(place({part:"15070",at:[0,39,z],colour:"spine"})));
range(-24,-16).forEach(z=>head.push(place({part:"3070b",at:[-1,39,z],colour:S})));
[-18,-17].forEach(z=>head.push(place({part:"3070b",at:[0,39,z],colour:S})));
[-3,-1,1].forEach(x=>head.push(place({part:"3069b",at:[x,39,-16],colour:S})));
section("Head",head);
// ---- LEGS (right side, mirrored) ----
const legs=[
  box({at:[4,0,-7],size:[4,13,3],colour:S,texture:"masonry"}),
  ...range(-7,-4).map(z=>place({part:"3040b",at:[4,13,z],colour:S,turn:90})),
  ...range(-7,-4).map(z=>place({part:"3040b",at:[6,13,z],colour:S,turn:270})),
  place({part:"3021",at:[5,0,-9],colour:S}),
  ...[5,6,7].map(x=>place({part:"54200",at:[x,0,-10],colour:"spine"})),
  box({at:[4,3,3],size:[4,11,6],colour:S,texture:"masonry"}),
  box({at:[5,0,3],size:[3,3,3],colour:S}),
  ...range(3,9).map(z=>place({part:"3040b",at:[4,14,z],colour:S,turn:90})),
  ...range(3,9).map(z=>place({part:"3040b",at:[6,14,z],colour:S,turn:270})),
  place({part:"3021",at:[5,0,1],colour:S}),
  ...[5,6,7].map(x=>place({part:"54200",at:[x,0,0],colour:"spine"})),
];
section("Legs",[...legs, mirror({axis:"x",about:0,ops:legs})]);
// ---- WINGS: stepped fan rising from the shoulders ----
const depths=[7,12,12,11,10,11,12,11,10,9,8,6];
const wing=[];
depths.forEach((dep,i)=>{ const x=2+i, y=15+2*i, z0=(i===0)?-4:-6;
  wing.push(floor({at:[x,y,z0],size:[6,2],layers:2,colour:S}));
  wing.push(floor({at:[x,y,z0+2],size:[6,dep-2],layers:2,colour:"membrane"}));
});
wing.push(place({part:"64847",at:[18,39,-6],colour:"spine"}));
section("Wings",[...wing, mirror({axis:"x",about:0,ops:wing})]);
// ---- TAIL: curls right around the hoard ----
const tsegs=[[-3,10,6,4,3,9],[-2,14,5,4,3,8],[-1,18,4,3,2,8],[1,20,4,3,2,7],[4,21,4,3,1,6],[7,21,4,3,1,5],[10,20,4,3,0,5],[13,18,3,3,0,4],[15,15,3,3,0,4],[16,12,2,3,0,3]];
const tail=tsegs.map(([x,z,w,d,y,h])=>box({at:[x,y,z],size:[w,h,d],colour:S,texture:"masonry"}));
[[-1,15,11],[0,11,15],[1,10,18],[3,9,21],[6,7,22],[9,6,22],[12,5,21],[14,4,19],[16,4,16],[17,3,13]].forEach(p=>tail.push(place({part:"15070",at:p,colour:"spine"})));
[10,12].forEach(z=>{tail.push(place({part:"3039",at:[-3,12,z],colour:S,turn:90}));tail.push(place({part:"3039",at:[1,12,z],colour:S,turn:270}));});
tail.push(box({at:[-1,12,10],size:[2,3,4],colour:S}));
tail.push(place({part:"3040b",at:[16,0,10],colour:S}));
tail.push(place({part:"3040b",at:[17,0,10],colour:S}));
section("Tail",tail);
// ---- HOARD ----
section("Hoard",[
  box({at:[7,0,10],size:[7,2,7],colour:"belly",interior:"solid"}),
  place({part:"4738a",at:[8,2,12],colour:"reddish brown"}),
  place({part:"4739a",at:[8,6,12],colour:"reddish brown"}),
  place({part:"39262",at:[12,2,15],colour:"pearl gold"}),
  place({part:"2343",at:[8,2,16],colour:"pearl gold"}),
  place({part:"30153",at:[7,2,11],colour:"trans red"}),
